/** COMSINHDR / COMSOUTHDR + DCIINPUTEVENT / DCITASKEVENT: canal de entrada y salida en línea. */
public record ComsCanal(MessageChannel entrada, MessageChannel salida,
                        SubscribableChannel eventosEntrada, SubscribableChannel eventosTarea) {}

/**
 * LIBRARY TIME_OUT (LIBACCESS = BYTITLE): la librería L091 se liga por título.
 * En Java es un puerto implementado por el servicio que sustituya a L091.
 */
public interface EnvioCancelacionesPort {
    /** Bloquea mientras el envío asíncrono esté activo, como la llamada ALGOL. */
    void enviaCancelaciones(ComsCanal canal);
}

@Component
@RequiredArgsConstructor
class ArranqueDependencias {
    final ControlVersionesClient ctlvers;   // LIBRARY CTLVER (FUNCTIONNAME="CTLVERS"): DAME_TIT
    final SoporteComsClient soporteComs;    // LIBRARY SHELL (FUNCTIONNAME="SOPORTECOMS."): CSIID
}

/** REPLACE E_MSG BY AUX UNTIL = ".", "L091ASIN": identificador usercode.L091ASIN. */
String resuelveVersionL091(String usercode) {
    String id = usercode + ".L091ASIN";
    return ctlvers.dameTitulo(id)                       // DAME_TIT(E_MSG, TITULO)
            .orElseGet(() -> {
                log.warn("ERROR AL LLAMAR A CONTROL DE VERSIONES");   // DISPLAY y continúa
                return props.tituloL091PorDefecto();                  // título compilado
            });
}

@Bean
IntegrationFlow cancelacionesEnLinea(ComsInboundAdapter coms) {   // ENABLE(COMSINHDR, "ONLINE")
    return IntegrationFlow.from(coms)
            .channel("cancelaciones.entrada")
            .get();
}

/** S500/LIST/P091/{csi}00/R000/{hora}. : directorio de volcados por CSI y hora de arranque. */
Path rutaVolcado(int csi, LocalTime arranque) {
    return Path.of(props.dirVolcados(), "%02d00".formatted(csi), "R000",
                   arranque.format(DateTimeFormatter.ofPattern("HHmmss")));
}

@Component
@RequiredArgsConstructor
public class ArranqueCancelacionesRunner implements ApplicationRunner {

    private final ArranqueDependencias deps;
    private final EnvioCancelacionesPort envio;   // ENVIA_CANCELACIONES IN TIME_OUT
    private final ComsCanal canal;

    @Override
    public void run(ApplicationArguments args) {
        inicia();                                  // INICIA;
        envio.enviaCancelaciones(canal);           // regresa solo al terminar el servicio
    }
}
